const D = { amount:.6, jitter:.5, energy:.6, speed:1, density:.5, hue:210, scale:1, x:.5, y:.5, style:'tape', act:'play', seed:0, label:'PLAY' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t, md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const nz=a=>{const s=Math.sin(a*74.3+P.seed*22.1+3.7)*19943.13;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const st=P.style, act=P.act, HUE=md(P.hue,360);
const cnv=drawingContext.canvas;
const oldOp=drawingContext.globalCompositeOperation;
const amt=clp(P.amount,0,1), jit=clp(P.jitter,0,1);

// ---- act dramaturgy ----
let degrade=1, dir=1, rollSpd=0.14, extraRoll=0;
if(act==='rewind'){ dir=-1; rollSpd=-0.6; degrade=1.25; extraRoll=0.4; }
else if(act==='degrade'){ degrade=clp(0.6+md(K.t*0.01,1)*1.3,0,2); } // noise creeps up then resets on t0
const wear=clp((0.4+0.9*amt)*degrade + A.rms*0.4, 0, 2);

// =============== horizontal line jitter: self-copy scan bands shifted ===============
drawingContext.imageSmoothingEnabled=false;
{
  const nB=Math.round(lrp(6,40,jit)*(0.5+0.5*wear));
  for(let i=0;i<nB;i++){
    const tw=Math.floor(K.t*22*(0.5+P.speed*0.5));
    const y=nz(tw*1.7+i*3.1)*Hh;
    const h=Math.max(2,u*(0.004+0.02*nz(i*5+tw)));
    const off=(nz(tw*3.3+i)-0.5)*u*0.06*jit*(0.4+wear) + Math.sin(K.t*3+i)*u*0.002;
    try{ drawingContext.drawImage(cnv, 0,y,W,h, off,y,W,h); }catch(e){}
  }
}
drawingContext.imageSmoothingEnabled=true;

// =============== thermal false-color remap (genuine: downsample luma -> heat ramp) ===============
if(st==='thermal'){
  const BW=120,BH=76; if(!S.tbuf){ S.tbuf=createGraphics(BW,BH); S.tbuf.pixelDensity(1); }
  const bx=64,by=40;
  S.tbuf.drawingContext.imageSmoothingEnabled=true;
  let px=null; try{ S.tbuf.drawingContext.clearRect(0,0,BW,BH); S.tbuf.drawingContext.drawImage(cnv,0,0,W,Hh,0,0,bx,by); px=S.tbuf.drawingContext.getImageData(0,0,bx,by).data; }catch(e){}
  const cw=W/bx, ch=Hh/by; noStroke();
  const heat=(g)=>{ const h=lrp(255,0,clp(g,0,1)); return [md(h,360), clp(60+g*40,0,100), clp(30+g*70,0,100)]; };
  for(let j=0;j<by;j++)for(let i=0;i<bx;i++){
    let g=0.4; if(px){ const k=(j*bx+i)*4; g=(px[k]*0.3+px[k+1]*0.59+px[k+2]*0.11)/255; }
    g=clp(g + Math.sin((i*0.7+j*1.1)+K.t*1.3)*0.06 + K.pulse*0.05,0,1);
    const c=heat(g); fill(c[0],c[1],c[2],96); rect(i*cw,j*ch,cw+1,ch+1);
  }
}

// =============== rolling tracking band (bright, noisy) — moves continuously ===============
{
  const by=md(K.t*u*rollSpd*(1+P.speed*0.2) + extraRoll*Math.sin(K.t*2),Hh*1.3)-Hh*0.15;
  const bh=u*(0.05+0.05*amt);
  blendMode(SCREEN); noStroke();
  fill(0,0,100, 10+18*wear); rect(0,by,W,bh*0.4);
  fill(0,0,100, 6+10*wear); rect(0,by-bh*0.5,W,bh*1.4);
  // torn-signal noise streaks inside the band
  const tw=Math.floor(K.t*30);
  for(let i=0;i<24;i++){ if(nz(tw+i)<0.5) continue; const yy=by+nz(tw*2+i)*bh; fill(0,0,100, 20*wear); rect(nz(tw*3+i)*W, yy, u*0.04*nz(i+tw), 1.5); }
  // chroma fringe at band edges
  drawingContext.globalCompositeOperation='screen';
  let c=color(0,85,100,40*wear); drawingContext.fillStyle=c.toString(); drawingContext.fillRect(0,by,u*0.02,bh);
  c=color(175,85,100,40*wear); drawingContext.fillStyle=c.toString(); drawingContext.fillRect(W-u*0.02,by,u*0.02,bh);
  drawingContext.globalCompositeOperation='source-over';
  blendMode(BLEND);
}

// =============== edge chroma fringe (whole frame sides) ===============
if(st!=='security'){
  const off=u*(0.003+0.008*amt)*(0.7+0.3*Math.sin(K.t*0.9));
  blendMode(SCREEN); noStroke();
  fill(0,80,100, 8+10*amt); rect(0,0,off*2,Hh);
  fill(175,80,100, 8+10*amt); rect(W-off*2,0,off*2,Hh);
  blendMode(BLEND);
}

// =============== grain / dropouts (self-generated, always moving) ===============
{
  const tw=Math.floor(K.t*24);
  const n=Math.round(lrp(30,150,clp(P.density,0,1))*(0.5+wear*0.5));
  blendMode(st==='security'?BLEND:SCREEN); noStroke();
  for(let i=0;i<n;i++){
    const x=nz(tw*1.3+i*2.1)*W, y=nz(tw*2.7+i)*Hh;
    const b=nz(tw*3+i*5); if(b<0.45) continue;
    const gh=(st==='thermal')?md(HUE+b*120,360):((st==='worn')?HUE:0);
    const gs=(st==='thermal')?60:(st==='worn'?25:0);
    fill(gh,gs,100, 12+20*wear*b); rect(x,y,u*(0.002+0.01*b), Math.max(1,u*0.0025));
  }
  blendMode(BLEND);
}

// =============== scanlines ===============
{
  const scy=md(K.t*u*0.05,3);
  blendMode(MULTIPLY); stroke(0,0,0, st==='security'?55:(st==='worn'?40:28)); strokeWeight(1);
  for(let y=-scy;y<Hh;y+=3) line(0,y,W,y);
  blendMode(BLEND);
}

// =============== color-cast / mono wash by style ===============
{
  blendMode(MULTIPLY); noStroke();
  if(st==='security'){ fill(140,25,80,55); rect(0,0,W,Hh); }         // green CCTV cast, desaturating
  else if(st==='worn'){ fill(35,20,72,30); rect(0,0,W,Hh); }          // yellowed tape
  blendMode(BLEND);
  if(st==='security'){ blendMode(SCREEN); fill(140,50,100,8); rect(0,0,W,Hh); blendMode(BLEND); }
  // vignette
  blendMode(MULTIPLY);
  const vig=drawingContext.createRadialGradient(W/2,Hh/2,u*0.2, W/2,Hh/2,u*0.8);
  vig.addColorStop(0,'rgba(255,255,255,0)'); vig.addColorStop(1,'rgba(0,0,0,'+(st==='security'?0.6:0.4)+')');
  drawingContext.fillStyle=vig; drawingContext.fillRect(0,0,W,Hh);
  blendMode(BLEND);
}

// =============== OSD timestamp / label (counts -> motion + authenticity) ===============
{
  const rate=dir*(1+ (act==='rewind'?4:0));
  const base=(act==='rewind')?5400:0;
  let tot=Math.floor(base + K.t*rate); tot=((tot%86400)+86400)%86400;
  const hh=Math.floor(tot/3600), mm=Math.floor(tot/60)%60, ss=tot%60;
  const pad=v=>(v<10?'0':'')+v;
  const tc=pad(hh)+':'+pad(mm)+':'+pad(ss);
  const blink=(Math.floor(K.t*1.5)%2===0);
  textFont('monospace'); textStyle(BOLD); textAlign(LEFT,TOP);
  const fs=u*0.032*P.scale; textSize(fs);
  const mx=W*0.055, myT=Hh*0.07;
  let tag=(''+P.label).toUpperCase().slice(0,10)||'PLAY';
  let sym= (act==='rewind')?'◀◀':'▶';
  if(st==='security'){ tag='REC'; sym=blink?'●':' '; }
  else if(st==='thermal'){ tag='THERMAL'; sym='░'; }
  const osdC=(st==='security')?[0,85,100]:(st==='thermal'?[30,90,100]:[0,0,100]);
  drawingContext.shadowColor='rgba(0,0,0,0.8)'; drawingContext.shadowBlur=u*0.006;
  noStroke(); fill(osdC[0],osdC[1],osdC[2], 88);
  text(sym+' '+tag, mx, myT);
  textAlign(RIGHT,BOTTOM);
  const dstr='SP  '+pad((hh%12)||12)+':'+pad(mm)+' '+(hh<12?'AM':'PM');
  text(dstr, W-mx, Hh-myT);
  textAlign(LEFT,BOTTOM);
  text(tc, mx, Hh-myT);
  drawingContext.shadowBlur=0;
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.imageSmoothingEnabled=true; drawingContext.shadowBlur=0; textStyle(NORMAL); noStroke(); noFill();
